from pathlib import Path
import base64, html, re, urllib.request, json

OUT=Path(__file__).resolve().parents[1]
ASSETS=OUT/'assets'
def esc(s): return html.escape(s)
def art(n, alt):
    if n in (0,1,2): alt='포스코 남성 사무직 직원과 AI 협업 장면: '+alt
    return f'<div class="art art{n}" role="img" aria-label="{alt}"></div>'
def pill(s): return f'<span class="pill">{s}</span>'
def rows(items): return '<div class="rows">'+''.join(f'<div class="row"><b>{a}</b><p>{b}</p></div>' for a,b in items)+'</div>'
def flow(items): return '<div class="flowline">'+ '<span class="arrow">→</span>'.join(f'<div class="node"><span class="node-no">0{i+1}</span><h3>{a}</h3><p>{b}</p></div>' for i,(a,b) in enumerate(items))+'</div>'
def code(s): return '<pre class="code">'+esc(s)+'</pre>'
def source(label,url): return f'<a class="source" href="{url}" target="_blank" rel="noopener">{label} ↗</a>'
slides=[]
def add(chapter,title,body,sub='',note='',cls='',attrs=''):
    slides.append(dict(chapter=chapter,title=title,body=body,sub=sub,note=note,cls=cls,attrs=attrs))

add('시작 · 16:00','내 업무를 아는 사람,<br>AI와 함께 만들다.',f'<div class="cover-copy"><p class="eyebrow">AI 기반 Vibe Coding · 초급</p><h1>내 업무를 아는 사람,<br>AI와 함께 만들다.</h1><p class="lede">말로 요청하고, 실행해 보고,<br>내 업무에 맞게 고치는 첫 한 시간.</p><div class="cover-date">2026. 09. 29. 화요일　16:00–17:00</div></div>{art(0,"업무 담당자가 AI 협업자에게 원하는 일을 설명하는 삽화")}',note='시작 1분. 교육 대상은 코딩 입문자. 설치를 동시에 따라 하는 실습이 아니라 개념과 시연 중심임을 알린다. 오늘 외울 것은 문법보다 요청·실행·확인의 흐름이다.',cls='cover')
add('시작','외우지 않아도 됩니다.\n흐름만 가져가세요.',f'<div class="split"><div><p class="big-quote">“그런 게 있구나.”<br><em>여기서 시작하면 충분합니다.</em></p>{rows([("설명하기","어떤 자료로, 무슨 일을, 어떤 결과로 만들지"),("확인하기","실행 결과가 내 업무 기준과 맞는지"),("다시 요청하기","다른 점과 오류를 구체적으로 알려주기")])}</div>{art(2,"사람이 프로그램 결과를 확인하고 AI가 고치는 삽화")}</div>',note='1분. 모든 개념을 한 번에 이해할 필요가 없다고 안내한다. 결과 확인의 책임은 사람에게 있다는 메시지를 자연스럽게 전달한다.')
add('시작','한 시간, 작은 업무 도구 하나', '<div class="agenda">'+''.join(f'<div><span>{time}</span><b>{name}</b><p>{desc}</p><strong>{mins}분</strong></div>' for time,name,desc,mins in [('16:00','이해','왜 AI 코딩인가',8),('16:08','기초','프로그램의 구조',12),('16:20','시연','요청 → 실행 → 수정',17),('16:37','환경','도구와 시작 설정',9),('16:46','연동','P-GPT의 연결 구조',9),('16:55','다음','첫 과제와 질문',5)])+'</div><p class="bottom-note">강사 시연 중심 · 설치 명령과 링크는 부록에서 다시 볼 수 있습니다.</p>',note='30초. 제작 시연을 중심에 놓았다. 예상 질문이 길어지면 개념 설명을 줄이고 16:55에는 마무리로 이동한다.')
add('01 · 왜 AI 코딩인가','AI에 필요한 것은\n여러분이 아는 업무입니다.',f'<div class="split"><div>{rows([("사람이 알려줄 것","업무의 목적, 예외, 좋은 결과의 기준"),("AI가 도울 것","코드 작성, 파일 수정, 실행과 오류 탐색"),("함께 할 것","작게 만들고 실제 결과를 확인하며 개선")])}<p class="takeaway">업무 지식이 구체적인 요구사항이 됩니다.</p></div>{art(0,"업무 지식을 AI에게 설명하는 담당자")}</div>',note='2분. 예: 미완료의 의미가 회사마다 다르다. 보류를 포함하는지, 담당자가 빈 행은 어떻게 처리하는지 알려줄 수 있는 사람은 현업 담당자다. AI가 회사 업무를 자동으로 안다고 가정하지 않는다.')
add('01 · 왜 AI 코딩인가','설명을 받는 데서,\n실제 파일을 바꾸는 데로', '<div class="compare"><div><span class="label">일반적인 텍스트 질의응답</span><h3>“어떻게 고치나요?”</h3><div class="bubble">이 부분을 이렇게 수정하세요.</div><p>사람이 코드를 옮기고 실행합니다.</p></div><div class="strong-block"><span class="label">Coding Agent의 작업 흐름</span><h3>“이 파일을 고치고 확인해줘.”</h3><div class="agent-path"><b>파일 찾기</b><span>→</span><b>수정하기</b><span>→</span><b>실행·확인</b></div><p>허용된 도구와 권한 안에서 직접 작업합니다.</p></div></div><p class="bottom-note">차이는 제품 이름보다 사용 가능한 도구에 있습니다. 챗봇에도 파일·실행 도구가 연결될 수 있습니다.</p>',note='2분. 중요한 포인트는 코드를 설명해 주는 데 그치지 않고 해당 파일의 필요한 부분을 찾아 고치는 것. 컴퓨터 전체나 마우스를 항상 제어할 수 있는 것은 아니다. GUI 제어는 별도 지원 도구와 권한이 필요하다.')
add('01 · 도입 시연','“완료된 업무는 숨겨줘.”','<div class="split demo-intro"><div><span class="demo-tag">LIVE 01 · 약 90초</span><p class="big-quote">작은 요청 하나가<br><em>화면의 동작을 바꿉니다.</em></p>'+rows([('요청','목록에서 완료 항목을 숨기는 버튼 추가'),('관찰','어느 파일을 읽고 무엇을 고치는가'),('확인','버튼을 누르면 미완료 항목만 남는가')])+'</div><div class="mini-app"><div class="window-head">업무 요청 목록 · 완성 예시</div><div class="task"><i></i>월간 실적 취합 <span>진행</span></div><div class="task muted"><i class="done"></i>회의실 예약 <span>완료</span></div><div class="task"><i></i>견적 검토 <span>대기</span></div><div class="fake-button">미완료만 보기</div><p class="small">실제 조작 예제는 본 시연에서 이어집니다.</p></div></div>',note='소개 챕터 종료까지 총 8분. 실제 Agent에 output/demo 폴더를 열고 “화면에 완료 항목을 숨기는 버튼을 추가하고 동작을 확인해줘”라고 요청한다. 라이브가 지연되면 이 완성 예시와 본 시연의 내장 데모를 사용한다. 이 화면 자체는 설명용 예시임을 말한다.')
add('02 · 기초 · 16:08','프로그램은 역할을 나눠 일합니다.',flow([('사람','원하는 작업'),('프론트엔드','보이는 화면'),('API','요청·응답 규약'),('백엔드','계산·처리'),('DB / 파일','저장된 자료')])+'<div class="underflow"><span>브라우저에서 입력</span><span>서버에서 처리하고 결과를 돌려줌</span></div><p class="takeaway">작은 도구는 HTML 파일만으로도 시작할 수 있습니다.</p>',sub='웹 앱의 대표 구조. 모든 프로그램에 서버와 DB가 필요한 것은 아닙니다.',note='2분. 화면은 주문 창구, API는 주문 형식, 백엔드는 처리 담당, DB는 보관소에 비유한다. Python은 백엔드의 한 선택지다. 정적 HTML 예제는 브라우저만으로 실행할 수 있음을 연결한다.')
add('02 · 기초','화면의 구조·모양·동작은\n서로 다른 역할입니다.','<div class="web-anatomy"><div class="wire-app"><div class="window-head">나의 업무 도구</div><h3>미완료 업무</h3><div class="wire-line"></div><div class="wire-line short"></div><div class="fake-button">완료 숨기기</div></div><div>'+rows([('HTML · 구조','제목, 목록, 입력란, 버튼을 놓습니다.'),('CSS · 모양','색, 글자, 간격, 화면 배치를 정합니다.'),('JavaScript · 동작','버튼을 누를 때 목록을 바꿉니다.')])+'</div></div><p class="bottom-note">웹 앱은 브라우저로 접근할 수 있어 배포가 편리합니다. 서버 운영·브라우저 호환·업데이트 관리는 여전히 필요합니다.</p>',note='2분. Frontend는 취향뿐 아니라 사용성, 접근성, 화면 크기, 동작 검증도 중요하다. Backend 역시 보안과 예외 처리가 중요하여 AI가 무조건 정확하다고 말하지 않는다.')
add('02 · 기초','라이브러리는 도구,\n가상환경은 프로젝트별 공구함','<div class="toolboxes"><div class="toolbox"><span class="label">프로젝트 A</span><h3>자료 정리 도구</h3><div class="tools"><b>Python</b><b>표 처리</b><b>차트</b></div><p>이 프로젝트가 쓰는 라이브러리와 버전</p></div><div class="toolbox second"><span class="label">프로젝트 B</span><h3>문서 변환 도구</h3><div class="tools"><b>Python</b><b>PDF</b><b>이미지</b></div><p>다른 프로젝트와 분리해 관리</p></div></div><div class="quote-strip">“이 프로젝트에 가상환경을 만들고, 필요한 라이브러리를 설치해줘.”</div>',note='1분 30초. 라이브러리는 미리 만들어진 기능을 재사용하는 것. 가상환경은 Python 패키지와 버전 충돌을 줄인다. 운영체제 전체를 격리하는 보안 장치는 아니다. 오늘 예제는 Python 기본 라이브러리만 사용한다.')
add('02 · 기초','터미널은 컴퓨터에게\n글로 지시하는 창입니다.','<div class="split"><div class="terminal"><div class="window-head">PowerShell · 명령 예시</div><p><span>PS&gt;</span> pwd</p><p class="terminal-result">C:\\work\\my-demo</p><p><span>PS&gt;</span> dir</p><p class="terminal-result">tasks.csv　 summarize.py</p><p><span>PS&gt;</span> python summarize.py</p><p class="terminal-result">report.html 생성 완료</p></div><div>'+rows([('pwd / dir','현재 위치 / 파일 목록 확인'),('cd .. / cls','상위 폴더로 이동 / 화면 지우기'),('ipconfig','네트워크 설정 확인')])+'<p class="takeaway">명령을 외우기보다<br>무엇을 실행하는지 확인하세요.</p></div></div>',note='1분 30초. CLI는 명령줄 인터페이스. CMD, PowerShell, Bash는 서로 다른 셸이며 명령이 다를 수 있다. Agent는 터미널을 통해 파일·프로그램을 다룬다. ipconfig는 네트워크 정보를 표시하므로 개인 화면 정보를 불필요하게 공유하지 않는다.')
add('02 · 기초','변경 이력과 실행 설정도\n프로젝트의 일부입니다.','<div class="gitline"><span class="commit">처음 완성</span><i></i><span class="commit">필터 추가</span><i></i><span class="commit">오류 수정</span></div>'+rows([('Git','변경 이력을 저장하고 이전 상태와 비교하는 도구'),('GitHub','Git 저장소를 원격에 보관하고 협업하는 서비스'),('환경변수','코드 밖에서 API 주소·모델 이름·인증값 등을 전달하는 설정')])+'<p class="bottom-note">환경변수는 자동 암호화 저장소가 아닙니다. 키는 코드·HTML·공개 저장소에 넣지 않습니다.</p>',note='1분 30초. 저장 버튼과 Git 커밋은 다르다. GitHub에 올릴지는 회사 정책과 자료 성격에 따라 정한다. 환경변수의 실제 값은 화면에 보여주지 말고 이름만 설명한다.')
add('02 · 기초','모델은 작업에 맞게,\n추론 노력은 필요한 만큼','<div class="model-row"><div><span class="label">GPT-5.6 Luna</span><h3>명확하고 반복적인 일</h3><p>속도와 비용을 중시할 때</p></div><div><span class="label">GPT-5.6 Terra</span><h3>일상적인 개발 작업</h3><p>성능과 비용의 균형</p></div><div><span class="label">GPT-5.6 Sol</span><h3>복잡한 분석과 수정</h3><p>더 깊은 검토와 완성도</p></div></div><div class="effort"><b>Low / Light</b><span>→</span><b>Medium</b><span>→</span><b>High / Extra High</b><p>복잡할수록 높여 보되, 시간·사용량과 결과를 함께 확인</p></div><p class="small">Max·Ultra 등 표시와 지원 범위는 모델·환경별로 다릅니다. Ultra는 여러 에이전트를 활용하는 모드입니다.</p>'+source('모델·추론 설정 공식 문서','https://learn.chatgpt.com/docs/models'),note='2분 30초. 원안의 Sol/Terra/Luna 비교를 유지한다. 현재 공식 목록에는 Astra도 있으므로 이 세 가지가 전체 모델 목록인 것처럼 설명하지 않는다. 제공 목록은 로그인·관리자 설정에 따라 다름. Artificial Analysis는 추가 비교 참고이며 점수만으로 업무 적합성을 판단하지 않는다.',attrs='data-noclick')
add('03 · 제작 시연 · 16:20','오늘 만들 것:\n업무 요청 요약기',f'<div class="split"><div>{pill("LIVE 02 · 17분")}{rows([("입력","담당자·업무·상태가 있는 CSV"),("처리","완료 여부를 구분하고 담당자별 건수 집계"),("출력","브라우저에서 읽는 HTML 보고서")])}<p class="takeaway">작게 완성한 뒤, 한 가지씩 더합니다.</p></div>{art(1,"사람과 AI가 프로그램 화면을 함께 조립하는 삽화")}</div>',note='1분. 예제 데이터는 가상 데이터다. 업무상 개인정보나 회사 자료를 넣지 않는다. output/demo/summarize.py와 tasks.csv, report.html이 백업으로 제공된다. HTML 데모는 외부 API를 호출하지 않는다.')
add('03 · 제작 시연','좋은 요청에는\n입력·처리·출력·기준이 있습니다.','<div class="prompt-sheet"><p><span>입력</span> tasks.csv에 담당자, 업무, 상태 열이 있어.</p><p data-step="1"><span>처리</span> 완료가 아닌 행을 모으고 담당자별 건수를 세어줘.</p><p data-step="2"><span>출력</span> Python으로 처리해서 report.html로 저장해줘.</p><p data-step="3"><span>기준</span> 원본은 보존하고, 필수 열 누락은 알기 쉽게 알려줘.<br>샘플로 실행한 뒤 집계가 맞는지도 확인해줘.</p></div><p class="bottom-note">“잘 만들어줘”를 실행하고 확인할 수 있는 조건으로 바꿉니다.</p>',note='2분. 네 줄을 한 줄씩 노출하며 읽는다. 프롬프트 문구를 외우는 대신 결과를 판단할 조건을 넣는다는 원칙을 강조한다. AI에게 먼저 계획을 설명해 달라고 해도 된다.')
add('03 · 제작 시연','개발 화면은 네 영역만 보세요.','<div class="editor-map"><div class="editor-title">VS Code + Coding Agent · 설명용 배치도 (실제 배치는 설정에 따라 다름)</div><div class="files"><span class="label">① 파일</span><p>tasks.csv</p><p>summarize.py</p><p>report.html</p></div><div class="editor-main"><span class="label">② 코드·변경 내용</span><div class="codeline w80"></div><div class="codeline w60"></div><div class="codeline w90"></div><div class="codeline w60"></div><div class="editor-terminal"><span class="label">③ 터미널·실행 결과</span><p>python summarize.py</p></div></div><div class="agent-pane"><span class="label">④ AI와 대화</span><div class="bubble">미완료 업무를<br>요약해줘.</div><p>파일 확인 → 수정 → 실행</p></div></div><p class="bottom-note">AI의 완료 메시지와 실제 파일·실행 결과를 함께 확인합니다.</p>',note='1분. 실제 VS Code 화면으로 전환해서 같은 네 영역을 짚는다. 여기의 그림은 실제 제품 스크린샷이 아닌 교육용 배치도다.')
add('03 · 제작 시연','Python이 자료를 정리하고,\nHTML이 결과를 보여줍니다.',flow([('tasks.csv','업무 6건'),('summarize.py','상태 분류·집계'),('report.html','미완료 4건')])+'<div class="run-result"><div>'+code('python summarize.py')+'</div><div><b>기대 결과</b><p>전체 6건 · 완료 2건 · 미완료 4건<br>미완료: 민지 2건 · 준호 1건 · 서연 1건</p></div></div><p class="small">이 숫자는 제공된 가상 예제의 확인 기준입니다.</p>',note='3분. Agent에 프롬프트를 전달하고 코드 생성과 실행을 지켜본다. Python 실행 후 생성된 report.html을 연다. 라이브 생성이 지연되면 제공된 완성본을 실행한다. 소스 코드 줄마다 설명하지 말고 입력→출력 관계를 보여준다.')
add('03 · 제작 시연','완성 다음에는,\n사용해 보며 고칩니다.','<div class="interactive-demo"><div><span class="demo-tag">직접 눌러보는 로컬 데모</span><p class="demo-question">“완료 항목을 숨기고,<br>담당자별로 볼 수 있게 해줘.”</p><div class="filters"><button id="toggle-done" type="button" aria-pressed="false">미완료만 보기</button><label for="owner">담당자</label><select id="owner"><option value="">전체</option><option>민지</option><option>준호</option><option>서연</option></select><button id="reset-demo" type="button">초기화</button></div><p id="demo-count" aria-live="polite"></p><p class="small">가상 데이터 6건 · 네트워크 호출 없음<br>미완료 = 상태가 ‘완료’가 아닌 업무</p></div><div class="demo-table"><div class="table-heading"><b>담당자</b><b>업무</b><b>상태</b></div><div id="task-rows"></div><p id="empty-state" hidden>조건에 맞는 업무가 없습니다.</p></div></div>',note='3분. 미완료 버튼을 누르면 4건. 민지를 선택하면 2건, 준호는 1건. 초기화하면 6건. 필터를 여러 순서로 조작해 결과가 유지되는지 확인한다. 이 데모는 작성된 HTML/JavaScript가 실행되는 예제로, 지금 AI가 코드를 생성하는 장면은 아니다.',attrs='data-noclick')
add('03 · 제작 시연','오류는 다음 요청의 재료입니다.',f'<div class="split"><div><div class="error-box">필수 열이 없습니다: 상태</div>{rows([("기대","미완료 업무만 집계하려고 했어."),("실제","‘상태’ 열이 없다는 오류가 나왔어."),("다음 요청","열 이름을 확인하고 원인을 설명해줘. 비슷한 파일에서도 같은 오류를 안내하도록 고쳐줘.")])}</div>{art(2,"프로그램 결과를 점검하고 문제를 수정하는 장면")}</div>',note='3분. 제공된 예제의 CSV 복사본에서 상태 열 이름을 바꿔 실행하고 명확한 오류를 보여준다. 오류를 숨기는 대신 원인을 이해하고 같은 종류의 입력에도 적용되게 고친다. 정상 입력으로 다시 실행하여 기존 동작이 유지되는지도 확인한다.')
add('03 · 제작 시연','반복되는 약속은\nAGENTS.md에 남깁니다.','<div class="split"><div class="document"><span class="label">AGENTS.md · 지침 예시</span><h3>이 프로젝트의 작업 규칙</h3><p>① 입력 원본은 수정하지 않습니다.</p><p>② 결과는 output 폴더에 저장합니다.</p><p>③ 오류에는 원인과 해결 방법을 적습니다.</p><p>④ 변경 후 정상·빈 입력·누락 열을 확인합니다.</p></div><div><p class="big-quote">“우리가 정한 작업 규칙을<br><em>AGENTS.md로 정리해줘.”</em></p><p class="lede">매번 설명하던 내용을<br>프로젝트의 공통 지침으로 만듭니다.</p>'+source('AGENTS.md 공식 문서','https://learn.chatgpt.com/docs/agent-configuration/agents-md')+'</div></div>',note='4분. 직접 문법을 외워 작성할 필요 없이 Agent에게 정리하도록 요청한다. 실제 파일을 열어 원하지 않는 규칙이 들어갔는지 검토한다. 파일이 존재한다고 모든 지침이 반드시 지켜진다는 보장은 없다. 새 세션에서 어떤 지침을 읽었는지 확인하도록 요청해 볼 수 있다.',attrs='data-noclick')
add('04 · 도구와 환경 · 16:37','도구는 하나의 경로로 시작하세요.','<div class="tool-routes"><div><span class="route-icon">▣</span><h3>전용 앱</h3><p>대화와 작업 관리를<br>앱에서 진행</p><span class="small">Codex 계열 앱 · Claude 계열 앱</span></div><div class="chosen"><span class="route-icon">〈/〉</span><h3>VS Code + 확장</h3><p>파일·코드·실행 결과를<br>한 화면에서 확인</p><span class="small">이 강의의 설명 기준</span></div><div><span class="route-icon">&gt;_</span><h3>CLI</h3><p>터미널에서<br>Agent를 실행</p><span class="small">Codex CLI · Claude Code 등</span></div></div><p class="bottom-note">원안에 제시된 사내 전용 앱 사용 제약을 전제로, 실제 허용 도구와 로그인 방법은 사내 안내를 확인합니다.</p>',note='2분. Cline, Kilo Code 같은 대안도 있지만 입문자는 여러 도구를 동시에 설치할 필요 없다. 회사의 앱 금지 정책은 제공 원안에 따른 맥락이며 현재 정책을 독립 검증한 것은 아니다. CLI가 회사 제한을 우회하는 방법인 것처럼 설명하지 않는다.')
add('04 · 도구와 환경','설치할 것과,\n필요할 때 추가할 것을 나눕니다.', '<div class="setup"><div><span class="label">오늘 예제의 기본 환경</span>'+rows([('Python','CSV를 읽고 HTML을 만드는 프로그램 실행'),('VS Code','프로젝트 폴더와 파일 확인'),('Codex 확장','에디터에서 AI에 작업 요청')])+'</div><div><span class="label">작업과 설치 방식에 따라</span>'+rows([('Python 확장','Python 실행·분석을 돕는 편의 도구'),('Node.js','npm 설치 방식이나 JavaScript 개발에 필요'),('Git','변경 이력을 남기고 복구할 때 사용')])+'</div></div><p class="bottom-note">Korean Language Pack과 색상 테마는 선택 사항입니다. 공식 다운로드 링크와 CLI 시작 순서는 부록에 있습니다.</p>',note='3분. HTML만 실행한다면 Python이 필요 없지만 이 강의의 CSV 예제에는 필요하다. Codex CLI의 npm 설치는 Node.js가 필요하고 독립 설치 경로는 별도다. 설치 후 버전 확인과 프로젝트 폴더 열기까지 보여준다.')
add('04 · 도구와 환경','권한은 “어디까지 맡길지”의 설정', '<div class="permission-map"><div class="boundary"><span class="label">작업 폴더</span><h3>파일 읽기 · 수정 · 실행</h3><p>교육용 복사본에서 시작</p><div class="inner-files">tasks.csv　 summarize.py　 report.html</div></div><div class="outside"><h3>범위를 넓히는 설정</h3><p>폴더 밖 접근 · 네트워크 · 외부 작업</p><p class="small">샌드박스: 가능한 작업 범위<br>승인 정책: 언제 확인을 요청할지</p></div></div><div class="quote-strip">Full Access는 접근 범위를 넓히는 선택입니다. 사내 허용 범위와 맡길 작업을 확인한 뒤 설정합니다.</div>'+source('권한·승인 공식 문서','https://learn.chatgpt.com/docs/agent-approvals-security'),note='4분. 원안의 “자꾸 안 물어보도록 Full Access”는 승인 횟수만으로 설명하지 않고 접근 범위와 승인 정책을 구분해 정리했다. 현재 CLI에서는 /permissions로 확인할 수 있다. 회사 관리 정책은 개인 설정으로 우회하지 않는다. 실제 업무 원본에 대한 광범위한 변경 권한을 교육 중 켜지 않는다.',attrs='data-noclick')
add('05 · 사내 AI 연동 · 16:46','AI로 만드는 것과,\n프로그램이 AI를 쓰는 것은 다릅니다.','<div class="compare"><div><span class="label">개발할 때</span><h3>사람 → Coding Agent → 코드</h3><div class="simple-scene">요청 <span>→</span> 작성·수정 <span>→</span> 프로그램</div><p>지금 만든 CSV 요약기는<br>실행할 때 LLM이 없어도 동작합니다.</p></div><div class="strong-block"><span class="label">실행할 때</span><h3>프로그램 → AI API → 응답</h3><div class="simple-scene">업무 내용 <span>→</span> AI 요약 <span>→</span> 문장</div><p>새 요약 기능을 붙이면<br>호출할 때 인증·연결·사용량이 필요합니다.</p></div></div>',note='1분 30초. 이 구분이 이번 챕터의 핵심. Coding Agent 로그인과 P-GPT API 인증은 별개일 수 있다. 정해진 규칙으로 셀 수 있는 건수 집계에는 LLM을 반드시 쓰지 않는다.')
add('05 · 사내 AI 연동','API는 연결 약속,\nAPI Key는 인증 정보',f'<div class="split"><div>{rows([("API","어느 주소로 어떤 형식의 요청을 보낼지 정한 약속"),("API Key","호출 권한과 사용 주체를 확인하는 인증 정보"),("서버에서 보관","키를 HTML에 넣지 않고 서버 측 설정으로 전달")])}<p class="takeaway">브라우저 → 우리 서버 → P-GPT → 결과</p></div>{art(3,"인증 키와 인증서를 통해 서버에 연결하는 구조의 삽화")}</div>',note='1분 30초. 열쇠 비유는 인증의 역할을 설명하기 위한 것이다. 키와 인증서는 서로 다르다. 브라우저에 키를 넣으면 소스와 네트워크 요청에서 노출될 수 있음을 설명한다.')
add('05 · 사내 AI 연동','P-GPT를 연결하기 전에\n네 가지를 확인합니다.','<div class="checklist"><div><b>01</b><h3>신청 경로</h3><p>신청 페이지 · 승인 담당 · 사용 목적</p></div><div><b>02</b><h3>접속 정보</h3><p>API 주소 · 인증 방식 · 사용 가능 모델</p></div><div><b>03</b><h3>호출 규약</h3><p>Responses 지원 여부 · 요청·응답 형식</p></div><div><b>04</b><h3>접속 환경</h3><p>사내망 · 프록시 · 인증서 · 사용 한도</p></div></div><p class="pending">사내 확인 필요: 실제 신청 링크·담당자·엔드포인트는 제공 자료에 없어 이 덱에 임의로 넣지 않았습니다.</p>',note='2분. 강의 전에 사내 공식 안내를 확보하여 이 슬라이드와 발표자 노트에 링크 및 담당자를 채운다. 현재는 준비 항목을 설명하는 장이며 실제 신청 절차를 검증한 자료는 아니다.')
add('05 · 사내 AI 연동','Responses API는\n입력을 보내고 결과를 받습니다.','<div class="split code-split"><div>'+code('from openai import OpenAI\nimport os\n\nclient = OpenAI()\nresponse = client.responses.create(\n    model=os.environ["OPENAI_MODEL"],\n    input="Summarize the pending tasks."\n)\nprint(response.output_text)')+'</div><div>'+rows([('준비','OpenAI SDK와 환경변수 설정'),('요청','model에 모델, input에 입력 전달'),('응답','output_text로 결과 텍스트 확인')])+'<p class="small">공개 OpenAI API의 개념 예제입니다.<br>OPENAI_API_KEY는 실행 환경에서 읽습니다.<br>P-GPT는 사내 공식 호출 예제에 맞춰 적용합니다.</p></div></div>'+source('Responses API 공식 예제','https://developers.openai.com/api/docs/guides/text'),note='1분 30초. 이 코드는 API 호출 구조를 설명하는 예제이며 실행 검증하지 않았다. 실제 키를 넣지 말고 실행도 선택 사항. P-GPT가 OpenAI와 호환된다고 단정하지 않는다. 주소·헤더·인증·모델·SDK 호환 여부를 사내 문서로 확인한 뒤 적용한다.',attrs='data-noclick')
add('05 · 사내 AI 연동','연결 오류는\n인증과 통신을 나눠 살펴봅니다.','<div class="connection">'+flow([('우리 프로그램','요청 생성'),('사내 통신 경로','인증서·프록시'),('P-GPT','인증·모델·응답')])+'</div>'+rows([('인증 오류','키·헤더·사용 권한을 확인'),('인증서 오류','사내 CA 적용 방법과 인증서 체인을 확인'),('시간 초과·접속 실패','API 주소·사내망·프록시 설정을 확인')])+'<p class="bottom-note">인증서 검증을 끄기보다, 사내 안내에 맞는 인증서를 적용합니다.</p>',note='1분 30초. 사내 인증서 경로, 구체 환경변수 이름은 런타임과 게이트웨이 정책에 따라 다르므로 임의로 정하지 않았다. 오류 메시지에서 키를 가린 뒤 원인별로 분류한다. 사내 연동의 실제 호출 성공은 별도 검증이 필요하다.')
add('06 · 마무리 · 16:55','첫 과제는,\n매주 반복하는 작은 일 하나',f'<div class="split"><div><div class="assignment"><span class="label">교육 후 15분 시작 과제</span><h3>내 업무를 세 문장으로 적기</h3><p>입력은 무엇인가요?</p><p>어떤 규칙으로 처리하나요?</p><p>결과가 맞는지 어떻게 확인하나요?</p></div><p class="takeaway">작게 요청하고 → 실행하고 → 확인하세요.</p></div>{art(1,"AI와 함께 작은 업무 도구를 완성하는 삽화")}</div>',note='2분. 예시: 파일명 정리, 표에서 조건에 맞는 행 추출, 텍스트를 읽기 쉬운 보고서로 변환. 실제 민감 자료보다 가상 샘플로 시작한다. 모르겠으면 AI에게 쉬운 설명과 작은 예제를 요청하도록 안내한다.')
add('06 · 질문','어떤 반복 업무를\n가장 먼저 바꾸고 싶으세요?',f'<div class="closing"><div><p class="big-quote">업무를 아는 여러분이<br><em>개발의 출발점입니다.</em></p><p class="lede">질문이 생기면 AI에게 묻고,<br>답과 실행 결과를 직접 확인해 보세요.</p><div class="end-keys">부록: 설치 링크 · 시작 명령 · 요청 문장<br>← → 이동　F 전체화면　? 도움말　M 목차　N 발표 노트</div></div>{art(0,"사람과 AI가 협업을 시작하는 장면")}</div>',note='3분 질의응답. 완성된 프로그램을 업무에 적용할 때는 데이터와 운영 환경에 맞는 확인이 추가로 필요하다고 답한다. 상세 설치 질문은 부록을 이용한다.',cls='closing-slide')
add('부록 A · 설치와 참고','공식 안내에서 시작하세요.','<div class="links-grid">'+''.join(f'<a href="{u}" target="_blank" rel="noopener"><b>{a}</b><span>{b} ↗</span></a>' for a,b,u in [('Python','설치 파일','https://www.python.org/downloads/'),('VS Code','편집기 설치','https://code.visualstudio.com/download'),('Codex CLI','설치·로그인·첫 작업','https://learn.chatgpt.com/docs/codex/cli'),('Node.js','npm 경로 이용 시','https://nodejs.org/en/download'),('Git','변경 이력 관리','https://git-scm.com/downloads'),('Artificial Analysis','모델 비교 참고','https://artificialanalysis.ai/')])+'</div><p class="small">공식 설치·설정 안내 확인일: 2026-09-16 · 회사에서 허용한 설치 경로와 버전을 우선합니다.<br>Cline · Kilo Code · Claude Code 등은 대안 도구의 예시이며 본 강의에서는 별도 설치를 진행하지 않습니다.</p>',note='참고용 부록. 발표 60분에는 포함하지 않는다. Python/VS Code/Node.js/Git은 공식 다운로드 페이지로 연결. 모델 비교 사이트는 평가 조건을 읽고 참고한다.',attrs='data-noclick')
add('부록 B · CLI 시작','CLI도 프로젝트 폴더에서 시작합니다.','<div class="split"><div>'+rows([('1 · 설치','공식 문서에서 사내 허용 설치 방식 선택'),('2 · 이동','교육용 프로젝트 폴더로 이동'),('3 · 실행','codex를 실행하고 허용된 방식으로 로그인'),('4 · 확인','모델과 권한을 확인하고 첫 요청 전달')])+'</div><div>'+code('npm install -g @openai/codex\n\ncd C:\\work\\my-demo\ncodex\n\n/model\n/permissions')+'<p class="small">위는 Node.js/npm을 사용하는 설치 예시입니다.<br>Windows 독립 설치 방식도 공식 문서에서 제공합니다.<br>/model·/permissions는 Codex 세션 내부 명령입니다.</p></div></div>'+source('Codex CLI 공식 안내','https://learn.chatgpt.com/docs/codex/cli'),note='참고용 부록. npm 명령은 PowerShell, 슬래시 명령은 Codex 대화창에 입력한다. 회사 로그인·망 정책은 별도다. 설치를 실제로 실행한 것은 아니다.',attrs='data-noclick')
add('부록 C · 다시 쓰는 요청 문장','모르는 순간에도\n이렇게 요청할 수 있습니다.','<div class="prompt-list"><div><b>배우기</b><p>“이 용어를 비개발자가 이해할 수 있게, 내 예제로 설명해줘.”</p></div><div><b>만들기</b><p>“입력은 이 파일이고, 결과는 이런 형식이야. 작은 버전부터 만들어줘.”</p></div><div><b>고치기</b><p>“기대한 결과는 A인데 B가 나왔어. 원인을 확인하고 고친 뒤 다시 실행해줘.”</p></div><div><b>남기기</b><p>“우리가 정한 작업 규칙과 확인 방법을 AGENTS.md에 정리해줘.”</p></div></div><div class="source-list">'+source('모델·추론','https://learn.chatgpt.com/docs/models')+source('권한·승인','https://learn.chatgpt.com/docs/agent-approvals-security')+source('AGENTS.md','https://learn.chatgpt.com/docs/agent-configuration/agents-md')+source('Responses API','https://developers.openai.com/api/docs/guides/text')+'</div>',note='공식 기술 출처와 재사용할 요청 문장을 모았다. 그림은 이 강의를 위해 AI로 생성한 개념 삽화이고, 도해와 화면 배치도는 교육용으로 제작했다. P-GPT 사내 절차·실제 호출은 미검증 상태다.',attrs='data-noclick')

CSS=r'''
:root{--void:#DEE7EE;--paper:#F5F8FB;--surface:#E8F1F7;--brand:#05507D;--brand-solid:#05507D;--ink:#17364A;--ink-soft:#405A6D;--ink-faint:#506474;--line:#B9CBD8;--line-soft:#D5E1E9;--accent:#076797;--highlight:#A9DFFA;--posco-light-blue:#00A5E5;--font-mono:'Consolas',monospace}
#stage{background:var(--paper)}
.slide{background:var(--paper);padding:64px 96px 94px;transition:opacity .18s ease}
.slide:before{content:'';position:absolute;top:66px;right:98px;width:42px;height:16px;border:3px solid var(--posco-light-blue);border-radius:15px;transform:rotate(-30deg)}
.slide h2{font-size:66px;line-height:1.22;margin:8px 0 18px;white-space:pre-line;max-width:1600px}
.kicker{font-size:22px;color:var(--accent);margin:0 0 9px;font-weight:800}
.slide-body{justify-content:center;gap:30px;min-height:0}
.slide-body>div,.slide-body>p{flex-shrink:0}
.lede{font-size:34px;line-height:1.55}
p{font-size:29px;line-height:1.55}
.small{font-size:22px;line-height:1.55;color:var(--ink-soft)}
.label,.eyebrow{font-size:23px;font-weight:800;color:var(--accent)}
.split{display:grid;grid-template-columns:1.08fr 1fr;gap:68px;align-items:center;width:100%}
.split>div{min-width:0}
.art{width:100%;aspect-ratio:1.5;background-size:200% 200%;background-repeat:no-repeat;border-radius:24px;box-shadow:0 12px 0 #DEEAF2}
.art0{background-position:0 0}.art1{background-position:100% 0}.art2{background-position:0 100%}.art3{background-position:100% 100%}
.cover .slide-body{display:block}.cover:before{display:none}.cover-copy{position:absolute;left:100px;top:130px;width:1050px;z-index:1}.cover h1{font-size:100px;line-height:1.2;color:var(--brand);margin:34px 0}.cover .art{position:absolute;right:65px;bottom:165px;width:760px}.cover .cover-date{font-size:25px;margin-top:56px;color:var(--ink-soft)}
.big-quote{font-size:45px;font-weight:800;line-height:1.5;margin-bottom:30px}.big-quote em{font-style:normal;color:var(--accent)}
.rows{width:100%}.row{display:grid;grid-template-columns:180px 1fr;gap:24px;border-bottom:1px solid var(--line);padding:21px 0}.row b{font-size:29px;line-height:1.5;color:var(--brand)}.row p{font-size:28px;color:var(--ink-soft)}
.takeaway{font-size:34px;font-weight:800;margin-top:30px;color:var(--brand)}
.agenda{display:grid;grid-template-columns:repeat(6,1fr);gap:0;border-top:4px solid var(--brand);margin-top:45px}.agenda>div{padding:34px 25px 30px;border-right:1px solid var(--line)}.agenda span{font-size:26px;color:var(--accent)}.agenda b{display:block;font-size:43px;margin:33px 0 20px}.agenda p{font-size:26px;min-height:88px}.agenda strong{font-size:58px;display:block;margin-top:36px}
.bottom-note{font-size:25px;color:var(--ink-soft);margin-top:24px}.compare{display:grid;grid-template-columns:1fr 1fr;gap:36px}.compare>div{padding:46px 42px;border:2px solid var(--line);border-radius:20px}.compare h3{font-size:36px;margin:24px 0 30px}.strong-block{background:var(--brand);color:var(--paper)}.strong-block h3,.strong-block p,.strong-block .label{color:var(--paper)}
.bubble{background:#E5F1F9;color:var(--ink);border-radius:20px 20px 20px 0;padding:28px;font-size:30px;margin:32px 0}.agent-path{display:flex;gap:18px;font-size:28px;align-items:center;margin:42px 0 50px}.agent-path b{border-bottom:3px solid #A9DFFA;padding-bottom:10px}
.demo-tag,.pill{display:inline-block;background:#A9DFFA;color:#17364A;font-size:23px;font-weight:800;padding:12px 20px;border-radius:30px;margin-bottom:24px}.mini-app,.wire-app{border:3px solid var(--brand);border-radius:20px;padding:0 35px 35px;background:#FFFFFF}.window-head{font-size:22px;border-bottom:1px solid var(--line);padding:20px 0;margin-bottom:18px;color:var(--ink-soft)}
.task{display:flex;align-items:center;gap:18px;padding:26px 0;border-bottom:1px solid var(--line);font-size:30px}.task span{margin-left:auto;font-size:24px}.task i{width:20px;height:20px;background:#A9DFFA;border-radius:50%}.task i.done{background:#8EAABF}.muted{opacity:.65}.fake-button{background:var(--brand);color:var(--paper);font-size:27px;display:inline-block;border-radius:12px;padding:15px 25px;margin:25px 0 10px}
.flowline{display:flex;align-items:center;gap:18px;width:100%}.node{flex:1;background:#E8F3FA;border:2px solid #BDD3E2;border-radius:22px;padding:32px 24px;min-height:230px}.node h3{font-size:32px;margin-top:20px}.node p{font-size:25px;color:var(--ink-soft)}.node-no{font-size:25px;font-weight:800;color:var(--accent)}.arrow{font-size:44px;color:var(--accent)}.underflow{display:flex;justify-content:space-around;border-bottom:2px solid var(--line);padding:25px;font-size:29px}
.web-anatomy{display:grid;grid-template-columns:650px 1fr;gap:90px;align-items:center}.wire-app h3{margin-top:30px}.wire-line{height:25px;background:#9FCADE;width:85%;margin:22px 0}.wire-line.short{width:60%}
.toolboxes{display:grid;grid-template-columns:1fr 1fr;gap:60px}.toolbox{padding:40px;border:3px solid var(--brand);border-radius:16px;background:#E8F3FA}.toolbox.second{background:#EDF2F7}.toolbox h3{font-size:42px;margin-top:20px}.tools{display:flex;gap:20px;margin:38px 0}.tools b{background:var(--paper);border:2px solid var(--line);padding:24px;font-size:30px}.quote-strip{background:var(--brand);color:var(--paper);border-radius:12px;font-size:31px;padding:28px 36px;line-height:1.55;margin-top:20px}
.terminal{background:#14354C;color:#F5F8FB;padding:24px 40px;border-radius:18px}.terminal .window-head{color:#CFDFEB}.terminal p{font-family:var(--font-body);font-size:30px;line-height:1.5;margin:18px 0}.terminal span{color:#A9DFFA}.terminal .terminal-result{color:#C4DAE9;padding-left:35px;margin-bottom:24px}
.gitline{display:flex;align-items:center;justify-content:center;margin-bottom:20px}.commit{padding:27px 45px;border:3px solid var(--brand);border-radius:60px;font-size:32px}.gitline i{height:4px;background:var(--brand);width:150px}
.model-row{display:grid;grid-template-columns:repeat(3,1fr);gap:34px}.model-row>div{border-top:4px solid var(--brand);padding:28px 20px}.model-row h3{font-size:35px;margin:22px 0}.model-row p{font-size:27px}.effort{display:flex;align-items:center;gap:24px;flex-wrap:wrap;background:#E6F1F8;padding:27px 30px;border-radius:15px;font-size:27px}.effort p{font-size:25px;flex-basis:100%}
.source{font-size:21px;color:var(--brand);text-decoration:underline;text-underline-offset:5px;display:inline-block;margin:8px 25px 0 0}.prompt-sheet{background:#E8F3FA;border:2px solid var(--line);border-radius:20px;padding:34px 45px}.prompt-sheet p{display:flex;gap:28px;font-size:34px;padding:22px 0}.prompt-sheet span{flex:0 0 90px;font-size:25px;font-weight:800;color:var(--accent);padding-top:7px}
.editor-map{height:570px;border:3px solid var(--brand);border-radius:20px;overflow:hidden;display:grid;grid-template-columns:280px 1fr 430px;grid-template-rows:62px 1fr;background:#FFFFFF}.editor-title{grid-column:1/-1;padding:17px 25px;background:var(--brand);color:var(--paper);font-size:22px}.files,.editor-main,.agent-pane{padding:30px;border-right:1px solid var(--line)}.files p{font-size:25px;margin-top:30px}.editor-main{position:relative}.codeline{height:17px;background:#7DB5D4;margin:29px 0}.w80{width:80%}.w60{width:60%}.w90{width:90%}.editor-terminal{border-top:2px solid var(--line);position:absolute;bottom:25px;left:30px;right:30px;padding-top:25px}.editor-terminal p{font-size:27px;margin-top:18px}.agent-pane p{font-size:25px}.agent-pane .bubble{font-size:28px}
.code{font-family:var(--font-body);font-size:28px;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere;background:#14354C;color:#F3F8FC;padding:35px;border-radius:16px;margin:0;tab-size:4}.run-result{display:grid;grid-template-columns:1fr 1.2fr;gap:60px;align-items:center}.run-result b{font-size:30px}.run-result p{margin-top:16px}.code-split{grid-template-columns:1.16fr 1fr;gap:40px}.code-split .code{font-size:26px}
.interactive-demo{display:grid;grid-template-columns:650px 1fr;gap:70px;align-items:center}.demo-question{font-size:38px;font-weight:800;margin:10px 0 30px}.filters{display:flex;flex-wrap:wrap;gap:14px;align-items:center}.filters button,.filters select{font:600 25px var(--font-body);border:2px solid var(--brand);padding:13px 18px;border-radius:10px;background:var(--paper);color:var(--brand)}.filters button[aria-pressed=true]{background:var(--brand);color:var(--paper)}.filters label{font-size:24px}.filters #reset-demo{border-color:var(--line)}#demo-count{font-size:36px;font-weight:800;margin:32px 0 20px}.demo-table{border:2px solid var(--line);border-radius:16px;overflow:hidden;background:#FFFFFF}.table-heading,.data-row{display:grid;grid-template-columns:125px 1fr 115px;gap:20px;padding:21px 28px;font-size:26px;align-items:center}.table-heading{background:var(--brand);color:var(--paper)}.data-row{border-bottom:1px solid var(--line-soft)}.status{font-size:23px;color:var(--accent)}.status.completed{color:var(--ink-soft)}#empty-state{padding:40px}
.error-box{background:#F2DED3;color:#873B2B;padding:28px;border-radius:15px;font-size:32px;font-weight:800;margin-bottom:20px}.document{background:#FFFFFF;border:2px solid var(--line);border-radius:8px;padding:44px;box-shadow:12px 12px 0 #DCE9F2}.document h3{font-size:40px;margin:27px 0}.document p{margin:25px 0;font-size:28px}
.tool-routes{display:grid;grid-template-columns:repeat(3,1fr);gap:32px}.tool-routes>div{padding:38px;border:2px solid var(--line);border-radius:18px}.route-icon{font-size:66px;font-weight:800;color:var(--brand);display:block;margin-bottom:22px}.tool-routes h3{font-size:39px}.tool-routes p{font-size:31px;margin:20px 0}.tool-routes .chosen{background:#E1F0F9;border:3px solid var(--brand)}.setup{display:grid;grid-template-columns:1fr 1fr;gap:80px}.setup .label{display:block;margin-bottom:20px}.setup .row{grid-template-columns:185px 1fr}
.permission-map{display:grid;grid-template-columns:1.15fr 1fr;gap:60px;align-items:center}.boundary{border:4px dashed var(--brand);padding:40px;border-radius:30px}.boundary h3{font-size:38px;margin:25px 0}.inner-files{padding:25px;background:#E1EFF8;font-size:27px;margin-top:25px}.outside p{margin:25px 0}.simple-scene{font-size:28px;padding:30px 0;margin:30px 0;border-block:1px solid currentColor}.simple-scene span{padding:0 13px}
.checklist{display:grid;grid-template-columns:1fr 1fr;gap:32px 70px}.checklist>div{position:relative;padding:20px 20px 22px 95px;border-bottom:1px solid var(--line)}.checklist b{position:absolute;left:0;top:20px;font-size:45px;color:var(--accent)}.checklist h3{font-size:37px}.checklist p{font-size:29px}.pending{font-size:25px;background:#E5F0F8;padding:25px;border-radius:12px}.connection .node{min-height:170px;padding:22px 28px}.connection .node h3{margin:12px 0}.connection .node-no{display:none}.assignment{border:3px solid var(--brand);padding:40px;border-radius:20px}.assignment h3{font-size:41px;margin:25px 0}.assignment p{font-size:33px;margin:22px 0}
.closing{display:grid;grid-template-columns:1.1fr 1fr;gap:50px;align-items:center}.closing .big-quote{font-size:48px}.end-keys{font-size:23px;color:var(--ink-soft);margin-top:50px;line-height:1.8}.links-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px 55px}.links-grid a{border-bottom:1px solid var(--line);padding:24px 10px;text-decoration:none;display:flex;align-items:center;justify-content:space-between;color:var(--brand)}.links-grid b{font-size:34px}.links-grid span{font-size:26px}.prompt-list>div{display:flex;gap:35px;padding:27px 0;border-bottom:1px solid var(--line)}.prompt-list b{font-size:29px;color:var(--accent);flex:0 0 100px}.prompt-list p{font-size:31px}
#chapter-tag{bottom:30px;font-size:20px}#counter{font-family:var(--font-body);bottom:30px}#progress{height:6px}#help .box{background:var(--paper)}#help dt{font-family:var(--font-body)}
#nav{position:absolute;bottom:20px;left:50%;transform:translateX(-50%);z-index:4;display:flex;gap:10px}#nav button{font:600 20px var(--font-body);background:var(--paper);border:1px solid var(--line);color:var(--brand);border-radius:7px;padding:9px 15px;cursor:pointer}button:focus-visible,select:focus-visible,a:focus-visible{outline:4px solid var(--accent);outline-offset:4px}
#menu,#notes{position:absolute;inset:45px;z-index:30;background:var(--paper);border:3px solid var(--brand);padding:40px;overflow:auto;display:none;border-radius:20px}#menu.on,#notes.on{display:block}.overlay-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:26px}.overlay-title button{font:600 25px var(--font-body);background:var(--brand);color:var(--paper);border:0;border-radius:8px;padding:12px 24px}#menu-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}#menu-grid button{text-align:left;font:600 23px var(--font-body);color:var(--brand);border:1px solid var(--line);background:#EAF2F8;border-radius:10px;padding:18px;min-height:65px;cursor:pointer}#notes-text{font-size:35px;line-height:1.8;max-width:1400px;white-space:pre-line}#notes h3{font-size:38px}button,a,select{touch-action:manipulation}
@media print{.slide{background:var(--paper)!important}#nav,#menu,#notes,#help,#counter,#chapter-tag,#progress{display:none!important}.art{box-shadow:none}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
'''

def main():
    for weight,name in [(400,'4Regular'),(600,'6SemiBold'),(800,'8ExtraBold'),(900,'9Black')]:
        dest=ASSETS/f'Paperlogy-{name}.woff2'
        if not dest.exists():
            urllib.request.urlretrieve(f'https://cdn.jsdelivr.net/gh/fonts-archive/Paperlogy/Paperlogy-{name}.woff2',dest)
    fontcss=''.join(f"@font-face{{font-family:Paperlogy;font-weight:{w};font-display:swap;src:url(data:font/woff2;base64,{base64.b64encode((ASSETS/f'Paperlogy-{n}.woff2').read_bytes()).decode()}) format('woff2')}}" for w,n in [(400,'4Regular'),(600,'6SemiBold'),(800,'8ExtraBold'),(900,'9Black')])
    artwork=base64.b64encode((ASSETS/'workshop-illustrations-posco.png').read_bytes()).decode()
    template=(OUT/'build/skeleton.html').read_text(encoding='utf-8')
    template=re.sub(r'<link rel="preconnect"[^>]*>','',template)
    template=re.sub(r'<link href="https://fonts.googleapis.com[^>]*>','',template)
    template=re.sub(r'<style>\s*@font-face.*?</style>', '<style>'+fontcss+'</style>',template,count=1,flags=re.S)
    template=template.replace('덱 제목 — 발표','AI 기반 Vibe Coding · 초급 | 60분 교육')
    template=template.replace('</head>',f'<style>{CSS}\n.art{{background-image:url(data:image/png;base64,{artwork})}}</style></head>')
    rendered=[]
    for s in slides:
        header='' if s['cls']=='cover' else f'<p class="kicker">{s["chapter"]}</p><h2>{s["title"]}</h2>'+ (f'<p class="lede">{s["sub"]}</p>' if s['sub'] else '')
        rendered.append(f'<section class="slide {s["cls"]}" data-chapter="{s["chapter"]}" data-title="{esc(re.sub("<[^>]*>"," ",s["title"]).replace(chr(10)," "))}" {s["attrs"]}>{header}<div class="slide-body">{s["body"]}</div></section>')
    start=template.index('<!-- ══ 1. 표지')
    end=template.index('<div id="chapter-tag">')
    template=template[:start]+'\n'.join(rendered)+'\n'+template[end:]
    controls='''<div id="nav" data-noclick><button type="button" id="prev" aria-label="이전 단계">←</button><button type="button" id="menu-open">목차 M</button><button type="button" id="notes-open">노트 N</button><button type="button" id="full">전체화면 F</button><button type="button" id="next" aria-label="다음 단계">→</button></div><div id="menu" role="dialog" aria-modal="true" aria-label="슬라이드 목차" data-noclick><div class="overlay-title"><h3>슬라이드 목차</h3><button type="button" id="menu-close">닫기 Esc</button></div><div id="menu-grid"></div></div><div id="notes" role="dialog" aria-modal="true" aria-label="발표자 노트" data-noclick><div class="overlay-title"><h3 id="notes-title">발표자 노트</h3><button type="button" id="notes-close">닫기 Esc</button></div><p id="notes-text"></p></div>'''
    template=template.replace('<div id="chapter-tag">',controls+'<div id="chapter-tag">')
    template=template.replace('<dt>?</dt>', '<dt>M / N</dt><dd>목차 / 발표자 노트</dd><dt>?</dt>')
    template=template.replace("slides.forEach((sl,i) => sl.classList.toggle('is-active', i === cur));","slides.forEach((sl,i) => {sl.classList.toggle('is-active', i === cur); sl.inert = i !== cur; sl.setAttribute('aria-hidden', String(i !== cur));}); updateNotes();")
    template=template.replace("addEventListener('keydown', e => {", """addEventListener('keydown', e => {
  if (e.key === 'Escape') { closeOverlays(); help.classList.remove('on'); return; }
  if (e.target.closest('input,select,textarea')) return;
  if (e.target.closest('button,a') && ['Enter',' '].includes(e.key)) return;
  if (e.key.toLowerCase() === 'm') { toggleOverlay(menu); return; }
  if (e.key.toLowerCase() === 'n') { toggleOverlay(notes); return; }
  if (menu.classList.contains('on') || notes.classList.contains('on')) return;
""")
    template=template.replace("input,button,a,select,textarea,#help", "input,button,a,select,textarea,#help,#menu,#notes,#nav")
    template=template.replace("document.documentElement.requestFullscreen?.();", "document.documentElement.requestFullscreen?.().catch(()=>{});")
    template=template.replace("let tx = 0, ty = 0;", "let tx = 0, ty = 0, touchBlocked = false, swipedAt = 0;")
    template=template.replace("tx = e.touches[0].clientX;", "touchBlocked = !!e.target.closest('button,a,input,select,textarea,#menu,#notes,#help'); tx = e.touches[0].clientX;")
    template=template.replace("const dx = e.changedTouches[0].clientX", "if(touchBlocked) return; const dx = e.changedTouches[0].clientX")
    template=template.replace("if (Math.abs(dx) > 46 && Math.abs(dx) > Math.abs(dy)) (dx < 0 ? next() : prev());", "if (Math.abs(dx) > 46 && Math.abs(dx) > Math.abs(dy)) { swipedAt=Date.now(); (dx < 0 ? next() : prev()); }")
    template=template.replace("stage.addEventListener('click', e => {", "stage.addEventListener('click', e => { if(Date.now()-swipedAt<500) return;")
    extra=r'''
const menu=document.getElementById('menu'), notes=document.getElementById('notes');
const noteData=NOTES_DATA;
let overlayOpener=null;
function updateNotes(){document.getElementById('notes-title').textContent=`${cur+1}. ${slides[cur].dataset.title}`;document.getElementById('notes-text').textContent=noteData[cur];}
function closeOverlays(){menu.classList.remove('on');notes.classList.remove('on');slides[cur].inert=false;document.getElementById('nav').inert=false;if(overlayOpener){overlayOpener.focus();overlayOpener=null;}}
function toggleOverlay(el){const was=el.classList.contains('on');closeOverlays();if(!was){overlayOpener=document.activeElement;el.classList.add('on');slides[cur].inert=true;document.getElementById('nav').inert=true;el.querySelector('button').focus();}}
document.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const box=menu.classList.contains('on')?menu:notes.classList.contains('on')?notes:null;if(!box)return;const list=[...box.querySelectorAll('button,a')];const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
document.getElementById('prev').onclick=prev;document.getElementById('next').onclick=next;
document.getElementById('menu-open').onclick=()=>toggleOverlay(menu);document.getElementById('notes-open').onclick=()=>toggleOverlay(notes);
document.getElementById('menu-close').onclick=closeOverlays;document.getElementById('notes-close').onclick=closeOverlays;
document.getElementById('full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>{});};
slides.forEach((s,i)=>{const b=document.createElement('button');b.type='button';b.textContent=String(i+1).padStart(2,'0')+' · '+s.dataset.title;b.onclick=()=>{closeOverlays();go(i,false);};document.getElementById('menu-grid').append(b);});
const tasks=[['민지','월간 실적 취합','진행'],['준호','회의실 예약','완료'],['서연','견적 검토','대기'],['민지','보고서 초안','진행'],['준호','재고 확인','대기'],['서연','일정 공유','완료']];
let pendingOnly=false;const owner=document.getElementById('owner'),toggle=document.getElementById('toggle-done');
function renderDemo(){const filtered=tasks.filter(t=>(!pendingOnly||t[2]!=='완료')&&(!owner.value||t[0]===owner.value));const holder=document.getElementById('task-rows');holder.replaceChildren();filtered.forEach(t=>{const row=document.createElement('div');row.className='data-row';t.forEach((v,i)=>{const cell=document.createElement('span');cell.textContent=v;if(i===2)cell.className='status'+(v==='완료'?' completed':'');row.append(cell);});holder.append(row);});document.getElementById('demo-count').textContent=`표시 ${filtered.length}건 / 전체 ${tasks.length}건`;document.getElementById('empty-state').hidden=filtered.length>0;toggle.setAttribute('aria-pressed',String(pendingOnly));toggle.textContent=pendingOnly?'전체 상태 보기':'미완료만 보기';}
toggle.onclick=()=>{pendingOnly=!pendingOnly;renderDemo();};owner.onchange=renderDemo;document.getElementById('reset-demo').onclick=()=>{pendingOnly=false;owner.value='';renderDemo();};renderDemo();
'''.replace('NOTES_DATA',json.dumps([s['note'] for s in slides],ensure_ascii=False))
    template=template.replace('go(fromHash(), false);\n})();',extra+'\ngo(fromHash(), false);\n})();')
    (OUT/'AI코딩교육_기초.html').write_text(template,encoding='utf-8')
    (OUT/'발표자_진행노트.md').write_text('# AI 코딩 교육 진행 노트\n\n- 60분 구성, 29장 본문 + 3장 부록\n- N 키로 현재 장의 노트를 볼 수 있습니다. 투사 화면에도 보이므로 강사용 참고 시 사용하세요.\n- 이미지와 글꼴은 HTML에 포함되어 오프라인 열기가 가능합니다. 외부 링크는 인터넷이 필요합니다.\n\n'+'\n\n'.join(f'## {i+1}. {re.sub("<[^>]*>"," ",s["title"]).replace(chr(10)," ")}\n\n{s["note"]}' for i,s in enumerate(slides)),encoding='utf-8')
    (OUT/'build/slides.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2),encoding='utf-8')
    print(f'Built {len(slides)} slides, {len(template.encode())/1048576:.2f} MB')
if __name__=='__main__':main()
